create table if not exists public.agency_members (auth_user_id uuid primary key references auth.users(id) on delete cascade, role text not null check (role in ('admin','designer','editor_filmmaker')), created_at timestamptz not null default now());
create table if not exists public.team_members (id bigint generated by default as identity primary key, auth_user_id uuid references auth.users(id) on delete set null, name text not null, email text not null unique, role text not null check (role in ('admin','designer','editor_filmmaker')), active boolean not null default true, created_at timestamptz not null default now());
create table if not exists public.candidates (id bigint generated by default as identity primary key, name text not null, electoral_number text, office text not null check (office in ('Deputado Federal','Deputado Estadual')), party text, city text, state text, investment_amount numeric(14,2), investment_source text, regions text, vote_projection text, candidate_team text, drive_folder_id text, drive_folder_url text, status text not null default 'active' check (status in ('active','paused','closed')), created_at timestamptz not null default now());
create table if not exists public.checklist_items (id bigint generated by default as identity primary key, candidate_id bigint not null references public.candidates(id) on delete cascade, category text not null check (category in ('document','electoral_requirement','strategy')), title text not null, label text, due_date date, completed boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.calendar_items (id bigint generated by default as identity primary key, candidate_id bigint not null references public.candidates(id) on delete cascade, title text not null, kind text not null check (kind in ('agenda','content','deadline','recording')), starts_at timestamptz not null, due_at timestamptz, completed boolean not null default false, assignee_id bigint references public.team_members(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.productions (id bigint generated by default as identity primary key, candidate_id bigint not null references public.candidates(id) on delete cascade, title text not null, format text not null, status text not null check (status in ('briefing','production','approval','changes','approved','published')), due_at timestamptz, drive_file_url text, reference_image_url text, notes text, assignee_id bigint references public.team_members(id) on delete set null, created_at timestamptz not null default now());
create table if not exists public.doubled_campaigns (id bigint generated by default as identity primary key, candidate_id bigint not null references public.candidates(id) on delete cascade, title text not null, partner_name text, region text, drive_folder_url text, notes text, created_at timestamptz not null default now());
alter table public.agency_members enable row level security;
alter table public.team_members enable row level security;
alter table public.candidates enable row level security;
alter table public.checklist_items enable row level security;
alter table public.calendar_items enable row level security;
alter table public.productions enable row level security;
alter table public.doubled_campaigns enable row level security;
create policy if not exists "members read own membership" on public.agency_members for select to authenticated using ((select auth.uid()) = auth_user_id);
create policy if not exists "agency members team" on public.team_members for all to authenticated using (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid()))) with check (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid())));
create policy if not exists "agency members candidates" on public.candidates for all to authenticated using (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid()))) with check (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid())));
create policy if not exists "agency members checklist" on public.checklist_items for all to authenticated using (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid()))) with check (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid())));
create policy if not exists "agency members calendar" on public.calendar_items for all to authenticated using (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid()))) with check (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid())));
create policy if not exists "agency members productions" on public.productions for all to authenticated using (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid()))) with check (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid())));
create policy if not exists "agency members doubled" on public.doubled_campaigns for all to authenticated using (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid()))) with check (exists (select 1 from public.agency_members m where m.auth_user_id=(select auth.uid())));
